package release

// S4c-2b-2 acceptance (protected, written by Claude): Evidence.quote_sha256 as the Harness
// defines it — sha256 of the NFKC quote with every Python str.split() whitespace removed.
// testdata/quote_digest_vectors.json was generated by the Harness quote_digest; the Harness
// test harness/tests/contracts/test_quote_digest_vectors.py checks the same file, so either
// side drifting fails a test.

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestQuoteDigestMatchesTheSharedVectors(t *testing.T) {
	raw, err := os.ReadFile("testdata/quote_digest_vectors.json")
	require.NoError(t, err)
	var vectors []struct {
		Name   string `json:"name"`
		Quote  string `json:"quote"`
		Digest string `json:"digest"`
	}
	require.NoError(t, json.Unmarshal(raw, &vectors))
	require.NotEmpty(t, vectors)
	for _, v := range vectors {
		t.Run(v.Name, func(t *testing.T) {
			require.Equal(t, v.Digest, QuoteDigest(v.Quote))
		})
	}
}
